def compute_order_amount(on_hand_inventory, pipeline_orders, last_demand, quoted_lead_time):
    base_stock = 283.8658226828985  # OPT_PARAM: {"initial": 283.8658226828985, "min": 100.0, "max": 600.0, "type": "float"}
    lead_time_adjustment = 2.301259608030635  # OPT_PARAM: {"initial": 2.301259608030635, "min": 0.0, "max": 200.0, "type": "float"}
    demand_smoothing = 0.0  # OPT_PARAM: {"initial": 0.0, "min": 0.0, "max": 1.0, "type": "float"}

    effective_lead_time = quoted_lead_time - 3  # center around minimum lead time
    adjusted_target = base_stock + lead_time_adjustment * effective_lead_time
    smoothed_demand = demand_smoothing * last_demand + (1 - demand_smoothing) * 100.0

    inventory_position = on_hand_inventory + sum(pipeline_orders)
    order_amount = max(0.0, adjusted_target + smoothed_demand - inventory_position)

    return order_amount

